/**
 * lucide-compat — a drop-in replacement for the `lucide-react` module surface.
 *
 * The shadcn-generated components in `src/components/` (and the Tecton layer
 * in `src/tecton/`) import their glyphs from `lucide-react` — that is CLI
 * managed code we do not edit. To make those components render Tecton glyphs
 * instead, point the bundler at this module:
 *
 *   // vite.config.ts
 *   export default defineConfig({
 *     resolve: {
 *       alias: { "lucide-react": "@tecton/react/icons/lucide-compat" },
 *     },
 *   })
 *
 * Every identifier lucide-react exports is still available (star re-export),
 * so the alias is safe for application code that imports other lucide icons.
 * For identifiers that have a Tecton equivalent *with a real SVG source*, the
 * generated map below shadows the lucide export with the Tecton component
 * (`ChevronDownIcon` → `./chevron-down`, …). Until SVGs land in `icons-src/`
 * this is a pure pass-through.
 *
 * Caveat: the generated icon files (`src/icons/*.tsx` and the map) import
 * `lucide-react` themselves for fallbacks. A blanket alias would make them
 * resolve to this module (a cycle), so scope the alias to importers outside
 * `src/icons/`. With Vite:
 *
 *   {
 *     name: "tecton-lucide-compat",
 *     enforce: "pre",
 *     resolveId(source, importer) {
 *       if (source !== "lucide-react" || !importer || importer.includes("/src/icons/")) return null
 *       return this.resolve("@tecton/react/icons/lucide-compat", importer, { skipSelf: true })
 *     },
 *   }
 *
 * `src/icons/lucide-compat.map.ts` is regenerated by `pnpm icons:build`
 * (scripts/build-icons.mts) — it scans the components for lucide imports and
 * checks `icons-src/` for matching SVGs. This file is hand-written and stable.
 */
export * from "./lucide-compat.map";
